#!/usr/bin/env python3
import sys, os, re, io, csv, gzip, json
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP
from datetime import datetime, date, timedelta, timezone

ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
FACT = {'kg': Decimal('1'), 'g': Decimal('0.001'), 'lb': Decimal('0.45392'), 'oz': Decimal('0.02837')}
MONTHS = {m: i + 1 for i, m in enumerate(
    ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'])}
COLS = {
    'east': ['id', 'type', 'shipped', 'gross', 'net', 'status', 'note'],
    'lakeside': ['id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'],
    'harbor': ['rec', 'ref', 'date', 'weight', 'state'],
    'river': ['t', 'ref', 'shipped', 'weight', 'status'],
    'west': ['id', 'typ', 'shipped', 'weight', 'status', 'note'],
}
DELIM = {'east': ',', 'lakeside': ',', 'harbor': '|', 'river': '\t', 'west': ';'}
BASE_DATE = {'east': 'YMD', 'lakeside': 'iso', 'harbor': 'iso', 'river': 'MM/DD/YYYY', 'west': 'DD.MM.YYYY'}
IDCOL = {'east': 'id', 'lakeside': 'id', 'harbor': 'ref', 'river': 'ref', 'west': 'id'}
TYPECOL = {'east': 'type', 'lakeside': 'kind', 'harbor': 'rec', 'river': 't', 'west': 'typ'}
SHIPCOL = {'east': 'shipped', 'lakeside': 'shipped', 'harbor': 'date', 'river': 'shipped', 'west': 'shipped'}
WCOL = {'east': 'gross', 'lakeside': 'gross_kg', 'harbor': 'weight', 'river': 'weight', 'west': 'weight'}
STCOL = {'east': 'status', 'lakeside': 'status', 'harbor': 'state', 'river': 'status', 'west': 'status'}
HARBOR_ST = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled', 'RET': 'returned', 'HLD': 'held'}
FW_ST = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}


def decode(b, depot):
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be')
    m = re.search(rb'^#[ \t]*charset[ \t]*:[ \t]*([^\s]+)', b[:2000], re.I | re.M)
    if m:
        try:
            return b.decode(m.group(1).decode('ascii'))
        except (LookupError, UnicodeDecodeError):
            pass
    return b.decode('utf-8', errors='replace')


def idnum(s):
    m = re.match(r'^\s*SH\D*(\d+)\s*$', s or '', re.I)
    return int(m.group(1)) if m else None


def norm_type(t):
    t = (t or '').strip().lower()
    if t.startswith('c') or t.startswith('a'):
        return 'C'
    if t.startswith('v'):
        return 'V'
    return 'N'


def norm_status(s):
    return re.sub(r'[ \-]+', '_', (s or '').strip().lower())


def parse_num(s, depot=None):
    s = s.strip()
    if depot == 'west':
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    return Decimal(s)


def to_date(s, form):
    s = s.strip()
    f = (form or '').strip().upper()
    if 'T' in s and re.match(r'^\d{4}-\d\d-\d\dT', s):
        return iso_dt(s)
    if re.match(r'^\d{1,2} [A-Za-z]{3}[a-z]* \d{4}$', s):
        d, mo, y = s.split()
        return date(int(y), MONTHS[mo[:3].lower()], int(d))
    if f == 'SERIAL':
        return date(1899, 12, 30) + timedelta(days=int(float(s)))
    p = re.split(r'[-/.]', s)
    p = [int(x) for x in p]
    if f in ('ISO', 'YMD'):
        return date(p[0], p[1], p[2])
    if f in ('DMY', 'DD/MM/YYYY', 'DD.MM.YYYY'):
        return date(p[2], p[1], p[0])
    if f == 'MM/DD/YYYY':
        return date(p[2], p[0], p[1])
    if f == 'YYYYMMDD':
        return date(int(s[:4]), int(s[4:6]), int(s[6:8]))
    if len(p) == 3 and p[0] > 31:
        return date(p[0], p[1], p[2])
    raise ValueError('date %r form %r' % (s, form))


def iso_dt(s):
    s = s.strip()
    if s.endswith('Z') or s.endswith('z'):
        s = s[:-1] + '+00:00'
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is not None:
        dt = dt.astimezone(timezone.utc)
    return dt.date()


def month_of(d):
    return '%04d-%02d' % (d.year, d.month)


def mk(num, typ, d, w, st):
    return {'num': num, 'type': typ, 'date': d, 'kg': w, 'status': st}


# ---------------- parsers: return (seq, [records]) ----------------

def logical_lines(text, quoted):
    """yield (kind, text): kind 'c' comment, 'r' record line."""
    lines = text.split('\n')
    i = 0
    while i < len(lines):
        l = lines[i].rstrip('\r')
        i += 1
        if l.strip() == '' or l.strip() == '\x0c':
            continue
        if l.startswith('#'):
            yield 'c', l
            continue
        if quoted:
            while l.count('"') % 2 == 1 and i < len(lines):
                l += '\n' + lines[i].rstrip('\r')
                i += 1
        yield 'r', l


def parse_delimited(text, depot):
    delim = DELIM[depot]
    cols = set(COLS[depot])
    seq = None
    header = None
    unit = None
    dform = None
    out = []
    for kind, l in logical_lines(text, delim == ','):
        if kind == 'c':
            m = re.match(r'^#\s*seq\s*=\s*(\d+)', l, re.I) or re.match(r'^#.*\bseq\s*=\s*(\d+)', l, re.I)
            if m and seq is None:
                seq = int(m.group(1))
            m = re.match(r'^#\s*([^:]+?)\s*:\s*(.*)$', l)
            if m:
                name = re.sub(r'\s+', ' ', m.group(1).strip().lower())
                val = m.group(2).strip()
                if name == 'seq':
                    if seq is None:
                        seq = int(val)
                elif name in ('unit', 'weight unit'):
                    mm = re.match(r'[A-Za-z]+', val)
                    if mm:
                        unit = mm.group(0).lower()
                elif name in ('dates', 'date format', 'date'):
                    dform = val
            continue
        if delim == ',':
            row = next(csv.reader([l], delimiter=','))
        else:
            row = l.split(delim)
        low = [x.strip().lower() for x in row]
        if low and all(x in cols for x in low):
            header = low
            continue
        if header is None:
            continue
        n = len(header)
        d = dict(zip(header, row))
        idc = IDCOL[depot]
        num = idnum(d.get(idc, ''))
        if num is None:
            continue
        rowunit = None
        wc = WCOL[depot]
        if len(row) == n + 1 and wc in header and depot != 'harbor':
            wi = header.index(wc)
            rowunit = row[wi + 1].strip().lower()
            row2 = row[:wi + 1] + row[wi + 2:]
            d = dict(zip(header, row2))
        typ = norm_type(d.get(TYPECOL[depot]))
        if typ == 'V':
            out.append(mk(num, 'V', None, None, None))
            continue
        # weight
        ws = (d.get(wc) or '').strip()
        wu = None
        if depot == 'harbor':
            m = re.match(r'^([\d.,]+)\s*([A-Za-z]+)$', ws)
            ws, wu = m.group(1), m.group(2).lower()
        else:
            m = re.match(r'^([\d.,]+)\s*([A-Za-z]+)$', ws)
            if m:
                ws, wu = m.group(1), m.group(2).lower()
        if wu is None:
            m = re.search(r'_(kg|g|lb|oz)$', wc)
            if m:
                wu = m.group(1)
        if wu is None:
            wu = rowunit or unit or 'kg'
        kg = parse_num(ws, depot) * FACT[wu]
        dt = to_date(d.get(SHIPCOL[depot]), dform or BASE_DATE[depot])
        if depot == 'west':
            dt = to_date(d.get(SHIPCOL[depot]), 'DD.MM.YYYY') if not re.match(r'^\d{4}-', d.get(SHIPCOL[depot], '').strip()) else dt
        st = d.get(STCOL[depot])
        if depot == 'harbor':
            st = HARBOR_ST.get((st or '').strip().upper(), st)
        out.append(mk(num, typ, dt, kg, norm_status(st)))
    return seq, out


def parse_north(text):
    seq = None
    out = []
    for kind, l in logical_lines(text, False):
        if kind == 'c':
            continue
        v = json.loads(l, parse_float=Decimal, parse_int=Decimal)
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and 'id' not in o:
                if seq is None and 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                continue
            num = idnum(str(o.get('id', '')))
            if num is None:
                continue
            k = (o.get('kind') or 'new').lower()
            typ = 'V' if k.startswith('v') else 'C' if k.startswith('a') or k.startswith('c') else 'N'
            if typ == 'V':
                out.append(mk(num, 'V', None, None, None))
                continue
            kg = None
            for key, val in o.items():
                m = re.match(r'^weight_(kg|g|lb|oz)$', key)
                if m:
                    kg = Decimal(str(val)) * FACT[m.group(1)]
            out.append(mk(num, typ, iso_dt(o['shipped_at']), kg, norm_status(o.get('status'))))
    return seq, out


def parse_central(b):
    root = ET.fromstring(b)
    seq = int(root.get('seq')) if root.get('seq') else None
    runit = (root.get('weight-unit') or 'kg').lower()
    out = []
    for e in root.iter('shipment'):
        num = idnum(e.get('id'))
        if num is None:
            continue
        typ = norm_type(e.get('type'))
        if typ == 'V':
            out.append(mk(num, 'V', None, None, None))
            continue

        def get(name):
            c = e.find(name)
            if c is not None:
                return c.text or ''
            return e.get(name)
        we = e.find('weight')
        ws = (we.text if we is not None else e.get('weight')) or '0'
        u = None
        if we is not None and we.get('unit'):
            u = we.get('unit')
        u = (u or e.get('weight-unit') or e.get('unit') or runit).lower()
        kg = Decimal(ws.strip().replace(',', '')) * FACT[u]
        dt = to_date(get('shipped'), 'iso')
        out.append(mk(num, typ, dt, kg, norm_status(get('status'))))
    return seq, out


FW = {
    41: ('FW3', dict(id=(0, 9), shipped=(9, 16), type=(16, 17), weight=(17, 24), status=(24, 25)), 'doy', Decimal('0.1') * FACT['lb']),
    42: ('FW1', dict(id=(0, 9), type=(9, 10), shipped=(10, 17), weight=(17, 25), status=(25, 26)), 'doy', FACT['g']),
    43: ('FW2', dict(type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26), status=(26, 27)), 'ymd', Decimal('0.01')),
}
FWNAME = {'FW3': 41, 'FW1': 42, 'FW2': 43}


def parse_south(text):
    seq = None
    out = []
    cur = None
    for l in text.split('\n'):
        l = l.rstrip('\r')
        if l.startswith('\x0c') or 'SHIPMENT LISTING' in l:
            continue
        if l.strip() == '':
            continue
        if l.startswith('#'):
            m = re.match(r'^#LAYOUT\s+(\w+)', l)
            if m:
                cur = FWNAME[m.group(1)]
            m = re.match(r'^#SEQ\s+(\d+)', l)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        n = len(l)
        if n not in FW:
            if cur is not None and n < cur:
                l = l.ljust(cur)
                n = cur
            else:
                continue
        name, f, dk, factor = FW[n]
        g = lambda k: l[f[k][0]:f[k][1]]
        num = idnum(g('id'))
        if num is None:
            continue
        typ = norm_type(g('type'))
        if typ == 'V':
            out.append(mk(num, 'V', None, None, None))
            continue
        s = g('shipped')
        if dk == 'doy':
            dt = date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:]) - 1)
        else:
            dt = date(int(s[:4]), int(s[4:6]), int(s[6:8]))
        kg = Decimal(int(g('weight'))) * factor
        out.append(mk(num, typ, dt, kg, norm_status(FW_ST.get(g('status').strip().upper(), g('status')))))
    return seq, out


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for fn in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, fn)
        if not os.path.isfile(p):
            continue
        depot = fn.split('-')[0].lower()
        b = open(p, 'rb').read()
        if b[:2] == b'\x1f\x8b':
            b = gzip.decompress(b)
        if depot == 'central':
            seq, recs = parse_central(b)
        elif depot == 'south':
            seq, recs = parse_south(decode(b, depot))
        elif depot == 'north':
            seq, recs = parse_north(decode(b, depot))
        elif depot in COLS:
            seq, recs = parse_delimited(decode(b, depot), depot)
        else:
            exports.setdefault(depot, [])
            continue
        exports.setdefault(depot, []).append((seq if seq is not None else -1, fn, recs))
    corrections = resends = 0
    current = {}
    for depot, exs in exports.items():
        cur = {}
        for seq, fn, recs in sorted(exs, key=lambda x: (x[0], x[1])):
            for r in recs:
                n = r['num']
                if r['type'] == 'N':
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r['type'] == 'C':
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur
    rank = lambda d: ORDER.index(d) if d in ORDER else len(ORDER)
    owners = {}
    for depot in sorted(current, key=lambda d: (rank(d), d)):
        for n in current[depot]:
            owners.setdefault(n, []).append(depot)
    handovers = sum(1 for v in owners.values() if len(v) > 1)
    depots = {d: [0, Decimal(0)] for d in sorted(exports)}
    months = {}
    for n, ds in owners.items():
        r = current[ds[0]][n]
        if r['status'] not in ('delivered', 'delivered_late'):
            continue
        depots[ds[0]][0] += 1
        depots[ds[0]][1] += r['kg']
        m = months.setdefault(month_of(r['date']), [0, Decimal(0)])
        m[0] += 1
        m[1] += r['kg']
    q = lambda x: float(x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    res = {
        'depots': {d: {'shipments': v[0], 'total_kg': q(v[1])} for d, v in depots.items()},
        'months': {k: {'shipments': months[k][0], 'total_kg': q(months[k][1])} for k in sorted(months)},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as f:
        json.dump(res, f, indent=2)


